<?php
session_start(); require_once '../middleware/staff.php'; require_once '../config/database.php'; require_once '../helpers/alert_response_helper.php';
$id=(int)($_GET['document']??0);$stmt=$pdo->prepare('SELECT ia.signed_file,s.student_number FROM internship_application ia JOIN internship_profile ip ON ip.internship_profile_id=ia.internship_profile_id JOIN student s ON s.student_id=ip.student_id JOIN group_class g ON g.group_id=s.group_id JOIN employee e ON e.user_id=? AND e.employee_type IN ("staff","teacher") WHERE ia.document_id=? AND ia.status="submitted" AND g.department_id=e.department_id LIMIT 1');$stmt->execute([$_SESSION['user_id'],$id]);$row=$stmt->fetch(PDO::FETCH_ASSOC);if(!$row||!$row['signed_file']){renderSweetAlertResponse('ไม่พบเอกสาร','ไม่พบเอกสารฉบับลงนาม หรือคุณไม่มีสิทธิ์ดาวน์โหลด','error','official_documents.php',404);}
$base=realpath(__DIR__.'/../uploads/internship_signed');$path=realpath($base.DIRECTORY_SEPARATOR.basename($row['signed_file']));if(!$base||!$path||!str_starts_with($path,$base.DIRECTORY_SEPARATOR)){renderSweetAlertResponse('ไม่พบไฟล์','ไม่พบไฟล์เอกสารฉบับลงนามที่ต้องการ','error','official_documents.php',404);}
header('Content-Type: application/pdf');header('Content-Disposition: attachment; filename="RMUTI_Pro-Ex_02-'.preg_replace('/[^A-Za-z0-9_-]/','_',$row['student_number']).'.pdf"');header('Content-Length: '.filesize($path));readfile($path);
